#include <cfloat>
#include <cmath>
#include <cstdio>

int main() {
    double a = 0.0;
    double b = 0.0;
    if (std::scanf("%lf %lf", &a, &b) != 2) return 1;
    if (a < -1000.0 || a > 1000.0 || b < -1000.0 || b > 1000.0) return 1;
    if (std::fabs(a - b) <= DBL_EPSILON * 10.0) {
        std::printf("same\n");
    } else {
        std::printf("diff\n");
    }
    return 0;
}
